head.b:skin:
/* SUSHI ELITE v112.0 - COMPACT & POLISHED */
:root {
    --primary: #ce1212; --primary-dark: #a00d0d;
    --secondary: #2d3436; --accent: #ffc107;
    --bg-body: #f8f9fa; --bg-card: #ffffff;
    --text-main: #1d1d1f; --text-muted: #636e72;
    --border-color: rgba(0,0,0,0.08);
    --radius-xl: 16px;
    --shadow-card: 0 4px 12px rgba(0,0,0,0.05);
    --z-marquee: 1040; --z-navbar: 1030; --z-floating: 1080;
    --blue-btn: #0d6efd;
}

[data-theme='dark'] { --bg-body: #121212; --bg-card: #1e1e1e; --text-main: #f5f5f7; --text-muted: #b2bec3; --border-color: rgba(255,255,255,0.1); }

body { font-family: "Inter", sans-serif; background: var(--bg-body); color: var(--text-main); padding-top: 140px; padding-bottom: 90px; overflow-x: hidden; transition: background 0.3s; }

/* --- COMPACT PROFILE HEADER (Fix) --- */
.profile-modern-header { 
    background: var(--bg-card); 
    padding: 15px 20px; 
    border-radius: 16px; 
    box-shadow: var(--shadow-card); 
    margin-bottom: 20px; 
    border: 1px solid var(--border-color);
    display: flex;
    align-items: center;
    gap: 15px;
}
.avatar-wrapper { position: relative; flex-shrink: 0; }
.avatar-img { width: 50px; height: 50px; border-radius: 50%; object-fit: cover; border: 2px solid #fff; box-shadow: 0 2px 8px rgba(0,0,0,0.1); }
.verified-badge { position: absolute; bottom: 0; right: 0; background: #0d6efd; color: #fff; width: 16px; height: 16px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 0.6rem; border: 1px solid #fff; }

.profile-info { flex-grow: 1; }
.profile-actions { display: flex; gap: 15px; align-items: center; }
.sub-link { font-size: 0.8rem; color: var(--text-muted); cursor: pointer; text-decoration: none; font-weight: 600; }
.sub-link:hover { color: var(--primary); }

/* --- CART LAYOUT FIX (Price Right) --- */
.cart-item-card { background: var(--bg-card); border: 1px solid var(--border-color); border-radius: 12px; padding: 15px; margin-bottom: 15px; display: flex; align-items: flex-start; gap: 15px; transition: 0.2s; position: relative; }
.cart-item-card:hover { border-color: var(--primary); box-shadow: var(--shadow-card); }
.cart-item-img { width: 100px !important; height: 100px !important; min-width: 100px !important; object-fit: cover; border-radius: 8px; background: #f0f0f0; flex-shrink: 0; }

/* Flex container for content */
.cart-item-content { flex-grow: 1; display: flex; flex-direction: column; height: 100px; justify-content: space-between; }

.qty-selector { display: flex; align-items: center; border: 1px solid var(--border-color); border-radius: 50px; overflow: hidden; width: fit-content; }
.qty-btn { border: none; background: var(--bg-body); width: 30px; height: 30px; display: flex; align-items: center; justify-content: center; font-weight: bold; color: var(--text-muted); transition: 0.2s; }
.qty-btn:hover { background: var(--border-color); color: var(--text-main); }
.qty-val { min-width: 30px; text-align: center; font-weight: 600; font-size: 0.9rem; }

.summary-card { background: var(--bg-card); border: 1px solid var(--border-color); border-radius: 16px; padding: 25px; position: sticky; top: 120px; }
.summary-row { display: flex; justify-content: space-between; margin-bottom: 12px; font-size: 0.95rem; color: var(--text-muted); }
.summary-total { border-top: 1px solid var(--border-color); padding-top: 15px; margin-top: 15px; display: flex; justify-content: space-between; align-items: center; font-weight: 800; font-size: 1.2rem; color: var(--text-main); }

/* ADDRESS CARD */
.address-card { border: 1px solid var(--border-color); border-radius: 12px; padding: 20px; height: 100%; transition: 0.2s; background: var(--bg-card); position: relative; cursor: pointer; }
.address-card:hover { border-color: var(--primary); background: var(--bg-body); }
.address-card.default { border-color: var(--blue-btn); border-width: 2px; }
.address-tag { position: absolute; top: 15px; right: 15px; background: #e7f1ff; color: var(--blue-btn); font-size: 0.7rem; font-weight: 700; padding: 4px 10px; border-radius: 20px; }

/* PROFILE TABS */
.nav-pills .nav-link { border-radius: 50px; color: var(--text-muted); font-weight: 600; padding: 8px 16px; transition: 0.2s; font-size: 0.85rem; margin-right: 5px; }
.nav-pills .nav-link.active { background-color: var(--primary); color: #fff; box-shadow: 0 4px 10px rgba(206, 18, 18, 0.3); }

/* HEADER */
.store-banner { position: fixed; top: 0; left: 0; width: 100%; height: 32px; background: rgba(220, 53, 69, 0.95); backdrop-filter: blur(5px); color: #fff; z-index: 1060; font-size: 0.7rem; font-weight: 700; text-transform: uppercase; display: flex; align-items: center; justify-content: center; letter-spacing: 1px; }
.header { background: var(--bg-card); height: 70px; z-index: var(--z-navbar); border-bottom: 1px solid var(--border-color); position: fixed; top: 32px; width: 100%; transition: top 0.3s; }
.breadcrumb-bar { position: fixed; top: 102px; left: 0; width: 100%; height: 40px; background: var(--bg-body); z-index: 1025; display: flex; align-items: center; padding: 0 15px; border-bottom: 1px solid var(--border-color); font-size: 0.85rem; overflow-x: auto; white-space: nowrap; transition: top 0.3s; }

/* UTILS */
.wish-btn-card { position: absolute; bottom: 10px; left: 10px; z-index: 10; width: 35px; height: 35px; background: var(--bg-card); border-radius: 50%; border: 1px solid var(--border-color); display: flex; align-items: center; justify-content: center; color: #ccc; transition: 0.2s; cursor: pointer; box-shadow: 0 2px 8px rgba(0,0,0,0.1); }
.wish-btn-card.active { color: var(--primary); border-color: var(--primary); background: #fff5f5; }
.badge-float { position: absolute; top: 10px; right: 10px; z-index: 10; padding: 4px 10px; border-radius: 4px; font-weight: 700; font-size: 0.65rem; color: #fff; text-transform: uppercase; box-shadow: 0 2px 5px rgba(0,0,0,0.2); }
.badge-hot { background: #ff4757; } .badge-low { background: #ffa502; animation: pulse 2s infinite; } .badge-out { background: #2f3542; }

.floating-cart { position: fixed; bottom: 30px; left: 50%; transform: translateX(-50%) translateY(200%); background: #1d1d1f; color: #fff; padding: 12px 25px; border-radius: 50px; z-index: 1100; display: flex; gap: 15px; align-items: center; box-shadow: 0 10px 40px rgba(0,0,0,0.3); transition: 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275); width: 90%; max-width: 380px; justify-content: space-between; cursor: pointer; }
.floating-cart.active { transform: translateX(-50%) translateY(0); }
.module-section { display: none; opacity: 0; transition: opacity 0.3s; }
.module-section.active { display: block; opacity: 1; }
.settings-item { padding: 15px; border-bottom: 1px solid var(--border-color); display: flex; justify-content: space-between; align-items: center; cursor: pointer; }
.btn-trash { color: #dc3545; background: rgba(220, 53, 69, 0.1); border: none; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; transition: 0.2s; cursor: pointer; }

#global-loader { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: var(--bg-body); z-index: 9999; display: flex; flex-direction: column; justify-content: center; align-items: center; transition: opacity 0.5s; }
.toast-container { position: fixed; bottom: 90px; left: 50%; transform: translateX(-50%); z-index: 1060; width: 90%; max-width: 350px; pointer-events: none; }
.custom-toast { background: var(--bg-card); color: var(--text-main); border-left: 4px solid var(--primary); box-shadow: 0 10px 30px rgba(0,0,0,0.15); border-radius: 12px; padding: 15px; margin-bottom: 10px; pointer-events: auto; display: flex; align-items: center; justify-content: space-between; animation: slideUp 0.3s; }
@keyframes slideUp { from { transform: translateY(20px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
.skeleton { background: linear-gradient(90deg, var(--bg-card) 25%, var(--border-color) 50%, var(--bg-card) 75%); background-size: 200% 100%; animation: loading 1.5s infinite; border-radius: 4px; }
@keyframes loading { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }
.delivery-bar-bg { height: 6px; background: #e9ecef; border-radius: 10px; overflow: hidden; margin-top: 5px; }
.delivery-bar-fill { height: 100%; background: #198754; width: 0%; transition: width 0.5s ease; }
.filter-scroll { display: flex; gap: 8px; overflow-x: auto; padding-bottom: 10px; scrollbar-width: none; }
.filter-scroll::-webkit-scrollbar { display: none; }
.filter-chip { white-space: nowrap; padding: 6px 16px; border-radius: 20px; background: var(--bg-card); border: 1px solid var(--border-color); color: var(--text-muted); font-weight: 600; cursor: pointer; transition: 0.2s; font-size: 0.85rem; }
.filter-chip.active { background: var(--primary); color: #fff; border-color: var(--primary); }
.flying-img { position: fixed; z-index: 9999; pointer-events: none; transition: all 0.8s cubic-bezier(0.19, 1, 0.22, 1); border-radius: 50%; opacity: 0.8; }

.qv-img-container { height: 250px; width: 100%; background: #f8f9fa; display: flex; align-items: center; justify-content: center; border-radius: 8px; overflow: hidden; margin-bottom: 15px; }
.qv-img { max-width: 100%; max-height: 100%; object-fit: contain; filter: drop-shadow(0 5px 15px rgba(0,0,0,0.08)); }
.btn-pill-group .btn-outline-secondary { border-radius: 50px; font-size: 0.75rem; padding: 6px 14px; margin-right: 6px; border-color: var(--border-color); color: var(--text-main); }
.btn-pill-group .btn-check:checked + .btn-outline-secondary { background-color: var(--secondary); color: #fff; border-color: var(--secondary); }
.order-card-modern { background: var(--bg-card); border: 1px solid var(--border-color); border-radius: 16px; padding: 20px; margin-bottom: 15px; transition: 0.2s; }
.order-thumbs { display: flex; gap: 10px; overflow-x: auto; padding-bottom: 10px; }
.order-thumb-img { width: 60px; height: 60px; border-radius: 8px; object-fit: cover; background: #f8f9fa; border: 1px solid var(--border-color); }
.status-pill-processing { background: #fff3cd; color: #856404; padding: 4px 12px; border-radius: 50px; font-size: 0.8rem; font-weight: 700; }
.status-pill-completed { background: #d1e7dd; color: #0f5132; padding: 4px 12px; border-radius: 50px; font-size: 0.8rem; font-weight: 700; }

.product-img-wrapper { position: relative; width: 100%; height: 0; padding-bottom: 75%; overflow: hidden; background: #f1f2f6; cursor: pointer; }
.product-img { position: absolute; top: 0; left: 0; width: 100%; height: 100%; object-fit: cover; transition: opacity 0.3s ease; }
.product-img.alt { opacity: 0; } .product-card:hover .product-img.alt { opacity: 1; }

body.script:
//
const API_URL = "https://script.google.com/macros/s/AKfycbxnDZiQY_tpQexinqIgq2H1xXEDvwrDpmnItcLh5uFGB1VqB12uh6M4-P6jGhSQmXwe/exec";
const IMG_FALLBACK = "https://via.placeholder.com/400x300?text=No+Image";

const App = {
    Config: { baseCurrency: 'MAD', freeShipThreshold: 200, waNumber: '212600000000', deliveryZones: {} },
    State: { catalog: [], cart: [], wishlist: [], recent: [], history: [], user: null, currency: 'MAD', exchange: { MAD:1, EUR:0.092, USD:0.1 }, activeCat: 'All', searchTerm: '', batchSize: 12, visibleCount: 0, activeCoupon: null, addresses: { home: null, office: null } },

    Utils: {
        fmt: (price) => {
            const c = App.State.currency;
            const val = (price * App.State.exchange[c]).toFixed(2);
            return c === 'MAD' ? `${val} DH` : (c === 'EUR' ? `€${val}` : `$${val}`);
        },
        save: (key, val) => localStorage.setItem(key, JSON.stringify(val)),
        load: (key) => { try { return JSON.parse(localStorage.getItem(key)) } catch(e) { return null } },
        el: (id) => document.getElementById(id) || { classList: { remove:()=>{}, add:()=>{} }, innerText: '', innerHTML: '', value: '' },
        getPriceObj: (i) => ({ now: i.price_MAD }),
        checkStock: (i) => {
            if(i.stock === 0) return { disabled: true, badge: '<span class="badge-float badge-out">Sold Out</span>' };
            if(i.stock < 5) return { disabled: false, badge: '<span class="badge-float badge-low">Low Stock</span>' };
            if(String(i.tags).includes('hot')) return { disabled: false, badge: '<span class="badge-float badge-hot">HOT</span>' };
            return { disabled: false, badge: '' };
        }
    },

    UI: {
        toast: (msg, type='info') => {
            const c = document.getElementById('toast-container');
            const t = document.createElement('div');
            t.className = `custom-toast border-${type}`;
            t.innerHTML = `<span>${msg}</span><button type="button" class="btn-close btn-close-sm" onclick="this.parentElement.remove()"></button>`;
            c.appendChild(t);
            setTimeout(() => t.remove(), 3000);
        },
        confirm: (title, msg, callback) => {
            App.Utils.el('conf-title').innerText = title;
            App.Utils.el('conf-msg').innerText = msg;
            const btn = document.getElementById('conf-btn');
            const modal = new bootstrap.Modal(document.getElementById('confirmModal'));
            const newBtn = btn.cloneNode(true);
            btn.parentNode.replaceChild(newBtn, btn);
            newBtn.onclick = () => { callback(); modal.hide(); };
            modal.show();
        },
        renderCard: (i, isGrid=true) => {
            const stock = App.Utils.checkStock(i);
            const altSrc = (i.tags && i.tags.includes('img-alt-url')) ? `https://picsum.photos/400/300?r=${i.id}` : '';
            const hoverAttr = altSrc ? `onmouseenter="this.querySelector('.product-img').src='${altSrc}'" onmouseleave="this.querySelector('.product-img').src='${i.image}'"` : '';
            const isWish = App.State.wishlist.includes(String(i.id));
            const heartClass = isWish ? 'active' : '';
            const heartIcon = isWish ? 'bi-heart-fill text-danger' : 'bi-heart';
            const colClass = isGrid ? 'col-6 col-md-4 col-lg-3' : 'col-6 col-md-3'; 
            return `
            <div class="${colClass}">
                <div class="product-card h-100" ${hoverAttr}>
                    ${stock.badge}
                    <div class="product-img-wrapper" onclick="App.QuickView.open('${i.id}')">
                        <img src="${i.image || IMG_FALLBACK}" class="product-img" loading="lazy" />
                        <button class="wish-btn-card ${heartClass}" data-id="${i.id}" onclick="event.stopPropagation();App.Wishlist.toggle('${i.id}')" type="button">
                            <i class="bi ${heartIcon}"></i>
                        </button>
                    </div>
                    <div class="p-3">
                        <h6 class="fw-bold text-truncate">${i.title}</h6>
                        <div class="d-flex justify-content-between align-items-center">
                            <span class="text-primary fw-bold">${App.Utils.fmt(i.price_MAD)}</span>
                            <button class="btn btn-sm btn-dark rounded-circle" ${stock.disabled ? 'disabled' : ''} onclick="App.Cart.add('${i.id}', this)" type="button">
                                <i class="bi bi-plus"></i>
                            </button>
                        </div>
                    </div>
                </div>
            </div>`;
        },
        renderQuickView: (p) => {
            const stock = App.Utils.checkStock(p);
            return `
            <div class="row g-0 h-100">
                <div class="col-md-5 qv-img-container">
                    <img src="${p.image || IMG_FALLBACK}" class="qv-img"/>
                </div>
                <div class="col-md-7 p-4 d-flex flex-column">
                    <div class="d-flex justify-content-between align-items-start">
                        <div style="flex:1; margin-right:10px">
                            <h4 class="fw-bold mb-1 lh-sm" style="font-size:1.25rem">${p.title}</h4>
                            <span class="badge bg-secondary text-uppercase" style="font-size:0.6rem; letter-spacing:0.5px">${p.category}</span>
                        </div>
                        <button class="btn-close" data-bs-dismiss="modal" type="button"></button>
                    </div>
                    <p class="text-muted small mt-2 mb-3 line-clamp-3" style="font-size:0.8rem">${p.desc || 'Freshly prepared with premium ingredients.'}</p>

                    <div class="mb-auto">
                        <label class="small fw-bold text-muted mb-2" style="font-size:0.7rem">SIZE VARIANT</label>
                        <div class="btn-group w-100 btn-pill-group" role="group">
                            <input type="radio" class="btn-check" name="qv-size" id="size-reg" value="1" checked onchange="App.QuickView.updatePrice(${p.price_MAD})">
                            <label class="btn btn-outline-secondary" for="size-reg">Regular</label>
                            <input type="radio" class="btn-check" name="qv-size" id="size-box" value="1.2" onchange="App.QuickView.updatePrice(${p.price_MAD})">
                            <label class="btn btn-outline-secondary" for="size-box">Box</label>
                            <input type="radio" class="btn-check" name="qv-size" id="size-party" value="1.5" onchange="App.QuickView.updatePrice(${p.price_MAD})">
                            <label class="btn btn-outline-secondary" for="size-party">Party</label>
                        </div>
                    </div>

                    <div class="d-flex align-items-center justify-content-between mt-4 pt-3 border-top">
                        <div class="d-flex align-items-center gap-2">
                            <span class="text-muted small">Total:</span>
                            <div class="h3 text-primary fw-bold m-0" id="qv-price-display">${App.Utils.fmt(p.price_MAD)}</div>
                        </div>
                        <div class="d-flex gap-2">
                            <div class="input-group input-group-sm" style="width: 90px;">
                                <button class="btn btn-outline-secondary" onclick="document.getElementById('qv-qty').stepDown()" type="button">-</button>
                                <input type="number" value="1" min="1" id="qv-qty" class="form-control text-center border-0">
                                <button class="btn btn-outline-secondary" onclick="document.getElementById('qv-qty').stepUp()" type="button">+</button>
                            </div>
                            <button class="btn btn-dark btn-sm rounded-pill fw-bold px-3" ${stock.disabled ? 'disabled' : ''} onclick="App.QuickView.addToCart('${p.id}')" type="button">ADD</button>
                        </div>
                    </div>
                </div>
            </div>`;
        },
        transition: (callback) => {
            const grid = document.getElementById('product-grid-root');
            if(grid) grid.innerHTML = Array(4).fill('<div class="col-6 col-md-3"><div class="skeleton" style="height:250px"></div></div>').join('');
            setTimeout(() => { callback(); }, 300);
        },
        updateHearts: (id, isActive) => {
            document.querySelectorAll(`.wish-btn-card[data-id="${id}"]`).forEach(b => {
                if(isActive) { b.classList.add('active'); b.innerHTML = '<i class="bi bi-heart-fill text-danger"></i>'; } 
                else { b.classList.remove('active'); b.innerHTML = '<i class="bi bi-heart"></i>'; }
            });
        },
        flyToCart: (imgEl) => {
            if(!imgEl) return;
            const cartBtn = document.getElementById('nav-cart-btn');
            if(!cartBtn) return;
            const fly = imgEl.cloneNode();
            const rect = imgEl.getBoundingClientRect();
            fly.classList.add('flying-img');
            fly.style.left = rect.left + 'px'; fly.style.top = rect.top + 'px';
            fly.style.width = rect.width + 'px'; fly.style.height = rect.height + 'px';
            document.body.appendChild(fly);
            const cartRect = cartBtn.getBoundingClientRect();
            setTimeout(() => { fly.style.left = (cartRect.left + 10) + 'px'; fly.style.top = (cartRect.top + 10) + 'px'; fly.style.width = '20px'; fly.style.height = '20px'; fly.style.opacity = '0'; }, 50);
            setTimeout(() => fly.remove(), 850);
        },
        toggleCurrency: () => {
            App.State.lastCurrencyChange = Date.now();
            const next = { MAD:'EUR', EUR:'USD', USD:'MAD' };
            App.State.currency = next[App.State.currency];
            App.Utils.el('curr-btn').innerText = App.State.currency;
            App.Utils.el('setting-curr-display').innerText = App.State.currency;
            App.Catalog.renderBatch(true); App.Cart.render();
            if(App.State.history.length > 0) App.Profile.renderHistory();
            localStorage.setItem('se_curr', App.State.currency);
            if(App.State.user) App.API.push('pref');
        },
        toggleTheme: () => {
            const body = document.body;
            const isDark = body.getAttribute('data-theme') === 'dark';
            body.setAttribute('data-theme', isDark ? 'light' : 'dark');
            if(document.getElementById('theme-toggle')) document.getElementById('theme-toggle').checked = !isDark;
            localStorage.setItem('se_theme', !isDark ? 'dark' : 'light');
        },
        hideLoader: () => { const l = document.getElementById('global-loader'); if(l) { l.style.opacity = '0'; setTimeout(() => l.remove(), 500); } }
    },

    Seo: {
        injectSchema: (p) => {
            const schema = { "@context": "https://schema.org/", "@type": "Product", "name": p.title, "image": [p.image], "offers": { "@type": "Offer", "priceCurrency": "MAD", "price": p.price_MAD } };
            App.Utils.el('json-ld-store').textContent = JSON.stringify(schema);
        }
    },

    Catalog: {
        search: (q) => { App.State.searchTerm = q.toLowerCase(); App.UI.transition(() => App.Catalog.renderBatch(true)); },
        renderFilters: () => {
            const c = document.getElementById('category-filters');
            if(!c) return;
            const cats = ['All', ...new Set(App.State.catalog.map(i => i.category))];
            c.innerHTML = cats.map(c => `<div class="filter-chip ${c==='All'?'active':''}" onclick="App.Catalog.setCat('${c}', this)">${c}</div>`).join('');
        },
        setCat: (cat, el) => {
            App.State.activeCat = cat;
            document.querySelectorAll('.filter-chip').forEach(e => e.classList.remove('active'));
            el.classList.add('active');
            App.UI.transition(() => App.Catalog.renderBatch(true));
        },
        renderBatch: (reset=false) => {
            const grid = document.getElementById('product-grid-root');
            if(!grid) return;
            if(reset) { grid.innerHTML = ''; App.State.visibleCount = 0; }
            let data = App.State.catalog.filter(i => (App.State.activeCat === 'All' || i.category === App.State.activeCat) && (i.title.toLowerCase().includes(App.State.searchTerm)));
            const batch = data.slice(App.State.visibleCount, App.State.visibleCount + App.State.batchSize);
            if(batch.length === 0 && reset) grid.innerHTML = '<div class="col-12 text-center py-5 text-muted">No items found.</div>';
            batch.forEach(i => grid.innerHTML += App.UI.renderCard(i));
            App.State.visibleCount += App.State.batchSize;
        }
    },

    Wishlist: {
        toggle: (id) => {
            const strId = String(id);
            const idx = App.State.wishlist.indexOf(strId);
            const isActive = (idx === -1);
            if(!isActive) { App.State.wishlist.splice(idx, 1); } 
            else { App.State.wishlist.push(strId); App.UI.toast("Added to Favorites"); }
            App.Utils.save('se_wish', App.State.wishlist);
            App.Utils.el('nav-wish-count').innerText = App.State.wishlist.length;
            App.UI.updateHearts(strId, isActive);
            App.API.push('wishlist');
            if(document.getElementById('profile-wishlist-grid') && document.getElementById('profile-wishlist-grid').offsetParent !== null) App.Wishlist.render();

            // INSTANT REDIRECT TO PROFILE SAVED TAB IF CLICKED FROM HEADER
            // Logic handled in Router for header clicks. This toggle is generic.
        },
        render: () => {
            let container = document.getElementById('wishlist-grid');
            if(document.getElementById('profile-wishlist-grid') && document.getElementById('profile-wishlist-grid').offsetParent !== null) container = document.getElementById('profile-wishlist-grid');
            if(!container) return;
            container.innerHTML = '';
            const items = App.State.catalog.filter(p => App.State.wishlist.includes(String(p.id)));
            if(items.length === 0) { container.innerHTML = '<p class="text-center text-muted mt-5 col-12">No favorites yet.</p>'; return; }
            items.forEach(i => container.innerHTML += App.UI.renderCard(i));
        },
        clear: () => { 
            if(App.State.wishlist.length === 0) return;
            App.UI.confirm('Clear Wishlist', 'Remove all favorites?', () => { App.State.wishlist=[]; App.Utils.save('se_wish',[]); App.Wishlist.render(); App.API.push('wishlist'); });
        }
    },

    Recent: {
        add: (id) => {
            App.State.recent = App.State.recent.filter(x => x !== id);
            App.State.recent.unshift(id);
            if(App.State.recent.length > 4) App.State.recent.pop();
            App.Utils.save('se_recent', App.State.recent);
            App.Recent.render();
        },
        render: () => {
            const c = document.getElementById('recent-grid');
            if(!c) return;
            const items = App.State.catalog.filter(i => App.State.recent.includes(String(i.id)));
            if(items.length===0) return;
            c.innerHTML = '';
            items.forEach(i => c.innerHTML += App.UI.renderCard(i, false));
        }
    },

    Auth: {
        openModal: () => new bootstrap.Modal(document.getElementById('authModal')).show(),
        login: () => {
            const p = App.Utils.el('login-phone').value;
            const pass = App.Utils.el('login-pass').value;
            if(!p) return alert('Enter Phone');
            fetch(API_URL, {method:'POST', body:JSON.stringify({action:'login', data:{phone:p, password:pass}})})
            .then(r=>r.json()).then(res=>{
                if(res.status==='success') { App.State.user = {id:res.userId, name:res.name, phone:p}; App.Utils.save('se_user', App.State.user); location.reload(); } else alert(res.message);
            });
        },
        register: () => {
            const n = App.Utils.el('reg-name').value;
            const p = App.Utils.el('reg-phone').value;
            const pass = App.Utils.el('reg-pass').value;
            fetch(API_URL, {method:'POST', body:JSON.stringify({action:'register', data:{name:n, phone:p, password:pass}})})
            .then(r=>r.json()).then(res=>{
                if(res.status==='success') { App.State.user = {id:res.userId, name:n, phone:p}; App.Utils.save('se_user', App.State.user); location.reload(); } else alert(res.message);
            });
        },
        logout: () => { App.UI.confirm('Logout', 'Are you sure?', () => { localStorage.removeItem('se_user'); location.reload(); }); },
        check: () => {
            const u = App.State.user;
            if(u) {
                App.Utils.el('profile-logged-in').style.display = 'block';
                App.Utils.el('profile-logged-out').style.display = 'none';
                App.Utils.el('user-name-display').innerText = u.name;
                App.Utils.el('user-phone-display').innerText = u.phone;
                App.Utils.el('auth-btn').innerHTML = '<i class="bi bi-person-check-fill text-success fs-5"></i>';
                App.Utils.el('setting-user-id').innerText = u.id.substring(0,8)+'...';

                App.Profile.renderHistory();
                App.Wishlist.render();
                App.Profile.renderAddresses(); 

                // Populate Addresses in Cart Dropdown
                const addrSelect = document.getElementById('cart-addr-select');
                if(addrSelect && (App.State.addresses.home || App.State.addresses.office)) {
                    addrSelect.innerHTML = '<option value="">Select Saved Address...</option>';
                    if(App.State.addresses.home) addrSelect.innerHTML += `<option value="Home">Home: ${typeof App.State.addresses.home === 'string' ? App.State.addresses.home : App.State.addresses.home.full}</option>`;
                    if(App.State.addresses.office) addrSelect.innerHTML += `<option value="Office">Office: ${typeof App.State.addresses.office === 'string' ? App.State.addresses.office : App.State.addresses.office.full}</option>`;
                }
            }
        }
    },

    Profile: {
        openAddressModal: (addrType = null) => {
            if(addrType) {
                const data = App.State.addresses[addrType.toLowerCase()];
                if(data && typeof data === 'object') {
                    document.getElementById('addr-type').value = addrType;
                    document.getElementById('addr-name').value = data.name || '';
                    document.getElementById('addr-street').value = data.street || '';
                    document.getElementById('addr-apt').value = data.apt || '';
                    document.getElementById('addr-city').value = data.city || '';
                    document.getElementById('addr-zip').value = data.zip || '';
                    document.getElementById('addr-country').value = data.country || '';
                }
            }
            new bootstrap.Modal(document.getElementById('addressModal')).show();
        },
        renderAddresses: () => {
            const c = document.getElementById('address-list-grid');
            if(!c) return;
            const a = App.State.addresses;
            let html = '';
            if(a.home) html += App.Profile.createAddrCard('Home', a.home);
            if(a.office) html += App.Profile.createAddrCard('Office', a.office);
            if(!html) html = '<div class="col-12 text-center text-muted py-3">No addresses saved.</div>';
            c.innerHTML = html;
        },
        createAddrCard: (type, data) => {
            const display = (typeof data === 'string') ? data : (data.full || `${data.street} ${data.apt}<br>${data.city}, ${data.zip}`);
            return `
            <div class="col-md-6"><div class="address-card">
                <span class="address-tag">${type}</span>
                <h6 class="fw-bold mb-3"><i class="bi bi-geo-alt-fill"></i> ${data.name || type}</h6>
                <p class="small text-muted mb-3">${display}</p>
                <button class="btn btn-sm btn-outline-dark rounded-pill px-3" onclick="App.Profile.openAddressModal('${type}')">Edit</button>
            </div></div>`;
        },
        saveAddress: () => {
            if(!App.State.user) return alert("Please login first");
            const btn = document.getElementById('save-addr-btn');
            btn.disabled = true; btn.innerText = "Saving...";

            const type = document.getElementById('addr-type').value;
            const addrData = {
                name: document.getElementById('addr-name').value,
                street: document.getElementById('addr-street').value,
                apt: document.getElementById('addr-apt').value,
                city: document.getElementById('addr-city').value,
                zip: document.getElementById('addr-zip').value,
                country: document.getElementById('addr-country').value,
                full: `${document.getElementById('addr-street').value} ${document.getElementById('addr-apt').value}, ${document.getElementById('addr-city').value}`
            };

            if(!addrData.street) { btn.disabled = false; btn.innerText = "Save Address"; return alert('Enter Street Address'); }

            fetch(API_URL, {method:'POST', body:JSON.stringify({
                action: 'updateAddress', 
                data: { userId: App.State.user.id, type: type, addressJson: JSON.stringify(addrData) }
            })}).then(r=>r.json()).then(res=>{
                if(res.status==='success') {
                    if(type==='Home') App.State.addresses.home = addrData;
                    else App.State.addresses.office = addrData;
                    App.Profile.renderAddresses();
                    bootstrap.Modal.getInstance(document.getElementById('addressModal')).hide();
                    App.UI.toast('Address Saved');
                } else {
                    alert("Save failed: " + res.message);
                }
                btn.disabled = false; btn.innerText = "Save Address";
            }).catch(e => { alert("Error saving"); btn.disabled = false; });
        },
        renderHistory: () => {
            const list = document.getElementById('order-history-list');
            if(!list) return;
            if(App.State.history.length === 0) { list.innerHTML = '<p class="text-muted small py-2">No orders found.</p>'; return; }
            list.innerHTML = '';
            App.State.history.forEach(o => {
                const displayTotal = App.Utils.fmt(parseFloat(o.total)); 
                let thumbsHtml = '';
                try {
                    const items = JSON.parse(o.items); 
                    if(items && items.length) {
                         thumbsHtml = items.slice(0, 3).map(itemName => {
                             const match = App.State.catalog.find(c => itemName.includes(c.title));
                             const img = match ? (match.image || IMG_FALLBACK) : IMG_FALLBACK;
                             return `<img src="${img}" class="order-thumb-img"/>`;
                         }).join('');
                    }
                } catch(e) {}
                const statusClass = (o.status === 'Completed' || o.status === 'Sent') ? 'status-pill-completed' : 'status-pill-processing';
                list.innerHTML += `
                <div class="order-card-modern">
                   <div class="d-flex justify-content-between mb-3">
                       <span class="fw-bold text-dark">#${o.id}</span>
                       <span class="text-muted small">${new Date(o.date).toLocaleDateString()}</span>
                   </div>
                   <div class="order-thumbs d-flex gap-2 mb-3">${thumbsHtml}</div>
                   <div class="d-flex justify-content-between align-items-center mb-2">
                       <span class="text-muted">Status</span><span class="${statusClass}">${o.status}</span>
                   </div>
                   <div class="d-flex justify-content-between align-items-center mb-3">
                       <span class="text-muted">Total</span><span class="fw-bold fs-5">${displayTotal}</span>
                   </div>
                   <div class="d-flex gap-2">
                       <button class="btn btn-primary flex-grow-1 rounded-pill" onclick="alert('Tracking...')">Track Order</button>
                       <button class="btn btn-light flex-grow-1 rounded-pill" onclick="App.Profile.showOrderDetail('${o.id}')">View Details</button>
                   </div>
                </div>`;
            });
        },
        showOrderDetail: (id) => {
            const o = App.State.history.find(x => x.id === id);
            if(!o) return;
            let itemsHtml = '<p class="text-muted">No item details.</p>';
            try {
                const items = JSON.parse(o.items);
                if(items && items.length) itemsHtml = `<div class="bg-light p-3 rounded mb-3">` + items.map(i => {
                    const match = App.State.catalog.find(c => i.includes(c.title));
                    const img = match ? (match.image || IMG_FALLBACK) : IMG_FALLBACK;
                    return `<div class="order-detail-row"><img src="${img}" class="od-img"/><span>${i}</span></div>`;
                }).join('') + `</div>`;
            } catch(e) {}
            const html = `<div class="p-3"><div class="d-flex justify-content-between align-items-center mb-3"><h5 class="m-0 fw-bold">#${o.id}</h5><span class="badge bg-primary">${o.status}</span></div><div class="mb-3 text-muted small">Date: ${new Date(o.date).toLocaleString()}</div>${itemsHtml}<div class="d-flex justify-content-between fw-bold border-top pt-3"><span>TOTAL</span><span class="text-primary">${App.Utils.fmt(parseFloat(o.total))}</span></div><button class="btn btn-outline-dark w-100 rounded-pill mt-4" data-bs-dismiss="modal">Close</button></div>`;
            document.getElementById('order-detail-body').innerHTML = html;
            new bootstrap.Modal(document.getElementById('orderDetailModal')).show();
        }
    },

    API: {
        init: () => {
            fetch(API_URL + '?action=checkStoreStatus').then(r=>r.json()).then(res=>{
                if(!res.isOpen) { const b = document.getElementById('store-closed-banner'); if(b) { b.classList.remove('d-none'); b.innerText = `⛔ STORE CLOSED (${res.hours})`; document.getElementById('main-header').style.top = '32px'; document.body.style.paddingTop = '172px'; } } else { document.getElementById('main-header').style.top = '0'; document.body.style.paddingTop = '140px'; }
                if(res.config) {
                    const sel = document.getElementById('chk-zone');
                    if(sel) { sel.innerHTML = '<option value="">Select Zone...</option>'; for(const k in res.config) { if(k.startsWith('Delivery_')) { const city = k.replace('Delivery_',''); App.Config.deliveryZones[city] = res.config[k]; sel.innerHTML += `<option value="${city}">${city} (+${res.config[k]} DH)</option>`; } } }
                    if(res.config.Free_Shipping_Threshold) App.Config.freeShipThreshold = res.config.Free_Shipping_Threshold;
                }
            }).catch(() => { });
            fetch(API_URL + '?action=getCatalog').then(r=>r.json()).then(res=>{
                if(res.status==='success') {
                    App.State.catalog = res.data.map(i => ({ id: i.id, title: i.title, category: i.category, price_MAD: parseFloat(i.price_MAD), stock: i.stock, image: i.image, tags: i.tags, desc: i.desc }));
                    App.Catalog.renderFilters(); App.Catalog.renderBatch(true); App.Recent.render();
                    if(App.State.user) App.API.syncDown(App.State.user.id);
                    App.UI.hideLoader();
                }
            }).catch(() => { App.UI.toast("API Error", "danger"); App.UI.hideLoader(); });
        },
        syncDown: (uid) => {
            fetch(API_URL + '?action=getUserData&userId='+uid).then(r=>r.json()).then(res=>{
                if(res.status==='success') {
                    if(res.cart && App.State.cart.length === 0) { App.State.cart = JSON.parse(res.cart); App.Cart.render(); }
                    if(res.wishlist) { App.State.wishlist = String(res.wishlist).split(','); App.Utils.el('nav-wish-count').innerText = App.State.wishlist.length; }
                    if(res.addresses) App.State.addresses = res.addresses;
                    if(res.orders) { App.State.history = res.orders; App.Profile.renderHistory(); }
                }
            });
        },
        push: (type) => {
            if(!App.State.user) return;
            let pl = {};
            if (type === 'cart') pl = { userId: App.State.user.id, cartJson: JSON.stringify(App.State.cart), currency: App.State.currency };
            else if (type === 'wishlist') pl = { userId: App.State.user.id, items: App.State.wishlist.join(',') };
            else if (type === 'pref') { fetch(API_URL, { method: 'POST', body: JSON.stringify({ action: 'updatePreference', data: { userId: App.State.user.id, currency: App.State.currency } }) }); return; }
            fetch(API_URL, {method:'POST', body:JSON.stringify({ action: type==='cart'?'syncCart':'syncWishlist', data: pl })});
        }
    },

    Cart: {
        add: (id, btn, qty=1, variant={mult:1, name:'Regular'}) => {
            const item = App.State.catalog.find(x => String(x.id) === String(id));
            if(!item) return;
            const exist = App.State.cart.find(c => c.id === id && c.variant.name === variant.name);
            if(exist) exist.qty += qty; else App.State.cart.push({ ...item, qty, variant });
            App.Utils.save('se_cart', App.State.cart);
            App.Cart.render(); App.API.push('cart'); App.UI.toast(`Added ${item.title}`);
            if(btn) App.UI.flyToCart(btn.closest('.product-card').querySelector('img'));
        },
        updateVariant: (idx, el) => {
            const selectedOption = el.options[el.selectedIndex];
            const newMult = parseFloat(selectedOption.value);
            const newName = selectedOption.text;

            // Update variant
            App.State.cart[idx].variant = { name: newName, mult: newMult };
            App.Utils.save('se_cart', App.State.cart);
            App.Cart.render(); // Re-render to update price
        },
        remove: (idx) => { 
            App.UI.confirm('Remove Item', 'Remove from cart?', () => { App.State.cart.splice(idx, 1); App.Utils.save('se_cart', App.State.cart); App.Cart.render(); App.API.push('cart'); });
        },
        empty: () => { 
            if(App.State.cart.length===0) return;
            App.UI.confirm('Empty Cart', 'Clear entire order?', () => { App.State.cart = []; App.Utils.save('se_cart', []); App.Cart.render(); App.API.push('cart'); });
        },
        applyCoupon: () => {
            const code = App.Utils.el('coupon-code').value.toUpperCase();
            const feed = App.Utils.el('coupon-feedback');
            feed.innerHTML = 'Verifying...';
            fetch(API_URL, {method:'POST', body:JSON.stringify({action:'checkCoupon', data:{code}})})
            .then(r=>r.json()).then(res=>{
                if(res.status==='success') { App.State.activeCoupon = res; feed.innerHTML = `<span class="text-success fw-bold">Active: ${code} (${res.discount*100}% Off)</span>`; App.Cart.calculateTotal(); } 
                else { App.State.activeCoupon = null; feed.innerHTML = `<span class="text-danger">Invalid Code</span>`; }
            });
        },
        fillAddress: () => {
            const type = document.getElementById('cart-addr-select').value;
            if(!type) return;
            const data = App.State.addresses[type.toLowerCase()];
            if(data && typeof data === 'object') {
                document.getElementById('chk-name').value = data.name || App.State.user.name;
                document.getElementById('chk-address').value = data.full;
            }
        },
        calculateTotal: () => {
            const zone = App.Utils.el('chk-zone').value;
            const del = App.Config.deliveryZones[zone] || 0;
            let sub = App.State.cart.reduce((a,b) => a + (b.price_MAD * b.variant.mult * b.qty), 0);
            App.Utils.el('cart-subtotal').innerText = App.Utils.fmt(sub);

            const bar = document.getElementById('delivery-bar');
            const msg = document.getElementById('delivery-msg');
            const amt = document.getElementById('delivery-amt');
            const thresh = App.Config.freeShipThreshold;

            let finalDel = del;
            if(sub >= thresh) { finalDel = 0; if(bar) { bar.style.width = '100%'; bar.style.backgroundColor = '#198754'; } if(msg) msg.innerText = "Free Delivery Unlocked!"; if(amt) amt.innerText = ""; } 
            else { const pct = (sub / thresh) * 100; if(bar) bar.style.width = pct + '%'; if(msg) msg.innerText = "Add more for Free Delivery"; if(amt) amt.innerText = App.Utils.fmt(thresh - sub); }

            let disc = 0;
            if(App.State.activeCoupon) { disc = sub * App.State.activeCoupon.discount; App.Utils.el('row-disc').classList.remove('d-none'); App.Utils.el('cart-disc').innerText = '-' + App.Utils.fmt(disc); }

            App.Utils.el('cart-delivery').innerText = finalDel === 0 ? "FREE" : App.Utils.fmt(finalDel);
            App.Utils.el('cart-total').innerText = App.Utils.fmt(sub + finalDel - disc);
            App.Utils.el('float-total').innerText = App.Utils.fmt(sub + finalDel - disc);
        },
        render: () => {
            const list = document.getElementById('cart-list');
            const count = App.State.cart.reduce((a,b) => a+b.qty, 0);
            App.Utils.el('nav-cart-count').innerText = count;
            App.Utils.el('float-count').innerText = count;

            const floatCart = document.getElementById('floating-cart');
            if (App.State.cart.length > 0) {
                floatCart.classList.add('active');
                App.Utils.el('cart-empty-state').classList.add('d-none');
                App.Utils.el('cart-content').classList.remove('d-none');
            } else {
                floatCart.classList.remove('active');
                App.Utils.el('cart-empty-state').classList.remove('d-none');
                App.Utils.el('cart-content').classList.add('d-none');
            }

            let sub = App.State.cart.reduce((a,b) => a + (b.price_MAD * b.variant.mult * b.qty), 0);
            App.Utils.el('float-total').innerText = App.Utils.fmt(sub);

            if(list) {
                list.innerHTML = App.State.cart.map((i, idx) => {
                    const lineTotal = i.price_MAD * i.variant.mult * i.qty;
                    return `
                    <div class="cart-item-card">
                        <img src="${i.image || IMG_FALLBACK}" class="cart-item-img"/>
                        <div class="flex-grow-1">
                            <div class="d-flex justify-content-between align-items-start">
                                <div>
                                    <h6 class="m-0 fw-bold">${i.title}</h6>
                                    <select class="form-select form-select-sm border-0 bg-light py-1 ps-2 pe-4" style="font-size:0.75rem; width:auto" onchange="App.Cart.updateVariant(${idx}, this)">
                                        <option value="1" ${i.variant.mult===1?'selected':''}>Regular</option>
                                        <option value="1.2" ${i.variant.mult===1.2?'selected':''}>Box</option>
                                        <option value="1.5" ${i.variant.mult===1.5?'selected':''}>Party</option>
                                    </select>
                                </div>
                                <div class="text-end">
                                    <div class="fw-bold text-primary">${App.Utils.fmt(lineTotal)}</div>
                                </div>
                            </div>
                            <div class="d-flex justify-content-between align-items-center mt-2">
                                <div class="qty-selector">
                                    <button class="qty-btn" onclick="App.Cart.add('${i.id}', null, -1, {mult:${i.variant.mult}, name:'${i.variant.name}'})">-</button>
                                    <span class="qty-val">${i.qty}</span>
                                    <button class="qty-btn" onclick="App.Cart.add('${i.id}', null, 1, {mult:${i.variant.mult}, name:'${i.variant.name}'})">+</button>
                                </div>
                                <div>
                                    <button class="btn btn-sm text-primary p-0 me-2" onclick="App.Cart.add('${i.id}', null, ${i.qty}, {mult:${i.variant.mult}, name:'${i.variant.name}'})"><i class="bi bi-files"></i></button>
                                    <button class="btn btn-sm text-danger p-0" onclick="App.Cart.remove(${idx})"><i class="bi bi-trash"></i></button>
                                </div>
                            </div>
                        </div>
                    </div>`;
                }).join('');

                const upsell = document.getElementById('cart-upsell');
                const suggestions = App.State.catalog.filter(x => !App.State.cart.some(c => c.id === x.id)).slice(0, 2);
                upsell.innerHTML = suggestions.map(s => App.UI.renderCard(s, false)).join('');
            }
            App.Cart.calculateTotal(); 

            // Auto-fill address
            const user = App.State.user;
            if(user && App.State.addresses.home && !document.getElementById('chk-address').value) {
                document.getElementById('chk-address').value = App.State.addresses.home.full || App.State.addresses.home;
            }
        },
        checkout: () => {
            const name = App.Utils.el('chk-name').value;
            const phone = App.Utils.el('chk-phone').value;
            const address = App.Utils.el('chk-address').value;
            const zone = App.Utils.el('chk-zone').value;
            if(!name || !phone || !zone) return alert('Fill all fields');

            if(!address) return alert("Please enter delivery address");

            const note = App.Utils.el('order-note').value;
            const time = App.Utils.el('order-time').value;
            const btn = document.getElementById('checkout-btn');
            if(btn) { btn.disabled = true; btn.innerText = 'Processing...'; }

            const cartData = App.State.cart.map(i => ({ id: i.id, qty: i.qty, variantMult: i.variant.mult, title: i.title }));
            const orderData = { 
                userId: App.State.user ? App.State.user.id : null, 
                name, phone, zone, 
                address: `${zone} - ${address}`, 
                cart: JSON.stringify(cartData), method: 'Cash', 
                couponCode: App.State.activeCoupon ? App.State.activeCoupon.code : null 
            };

            fetch(API_URL, { method: 'POST', body: JSON.stringify({ action: 'placeOrder', data: orderData }) })
            .then(r => r.json())
            .then(res => {
                if(res.status === 'success') {
                    App.State.cart.forEach(c => { if(!App.State.wishlist.includes(String(c.id))) App.State.wishlist.push(String(c.id)); });
                    App.Utils.save('se_wish', App.State.wishlist);
                    App.API.push('wishlist');
                    App.State.cart = []; App.Utils.save('se_cart', []);
                    let msg = `*NEW ORDER ${res.orderId}*%0A👤 ${name} (${phone})%0A🚚 ${orderData.address}%0A🕒 1H%0A📝 ${note}%0A--------------------%0A`;
                    cartData.forEach(i => msg += `🍱 ${i.qty}x ${i.title}%0A`);
                    msg += `💰 *TOTAL: ${App.Utils.fmt(res.secureTotal)}*`;
                    window.open(`https://wa.me/${App.Config.waNumber}?text=${msg}`, '_blank');
                    location.reload();
                } else { alert(res.message); if(btn) { btn.disabled = false; btn.innerText = 'PLACE ORDER'; } }
            });
        }
    },

    QuickView: {
        open: (id) => {
            const p = App.State.catalog.find(x => String(x.id) === String(id));
            if(!p) return;

            if(App.Seo) App.Seo.injectSchema(p); 
            App.Recent.add(id);

            document.getElementById('qv-body').innerHTML = App.UI.renderQuickView(p);
            new bootstrap.Modal(document.getElementById('quickViewModal')).show();
        },
        updatePrice: (base) => {
            const mult = parseFloat(document.querySelector('input[name="qv-size"]:checked').value);
            document.getElementById('qv-price-display').innerText = App.Utils.fmt(base * mult);
        },
        addToCart: (id) => {
            const qty = parseInt(document.getElementById('qv-qty').value);
            const el = document.querySelector('input[name="qv-size"]:checked');
            const variant = { mult: parseFloat(el.value), name: document.querySelector(`label[for="${el.id}"]`).innerText };
            App.Cart.add(id, null, qty, variant);
            bootstrap.Modal.getInstance(document.getElementById('quickViewModal')).hide();
        }
    },

    Router: {
        go: (route) => {
            App.State.currentView = route;
            window.scrollTo(0,0);
            document.querySelectorAll('.module-section').forEach(e => e.classList.remove('active'));
            const target = document.getElementById(route + '-module');
            if(target) target.classList.add('active');

            if(route === 'wishlist') {
                if(App.State.user) {
                    const target = document.getElementById('profile-module');
                    target.classList.add('active');
                    document.querySelector('button[data-bs-target="#tab-wish"]').click();
                } else {
                    const w = document.getElementById('wishlist-module');
                    w.classList.add('active');
                }
            }

            if(route === 'settings') {
                const target = document.getElementById('profile-module');
                target.classList.add('active');
                document.querySelector('button[data-bs-target="#tab-settings"]').click();
            }

            if(route === 'cart') App.Cart.render();
            if(route === 'profile') App.Auth.check();

            const bc = document.getElementById('breadcrumbs');
            if(bc) {
                if (route === 'home') bc.innerHTML = `<span class="fw-bold"><i class="bi bi-house-door-fill"></i> Home</span>`;
                else bc.innerHTML = `<span class="crumb-link" onclick="App.Router.go('home')">Home</span> <span class="mx-1">/</span> <b class="text-dark text-capitalize">${route}</b>`;
            }
        }
    }
};

document.addEventListener('DOMContentLoaded', () => {
    // Safe AOS Init
    if (typeof AOS !== 'undefined') { AOS.init(); }

    App.State.cart = App.Utils.load('se_cart') || [];
    App.State.wishlist = App.Utils.load('se_wish') || [];
    App.State.recent = App.Utils.load('se_recent') || [];
    App.State.user = App.Utils.load('se_user');

    const storedTheme = localStorage.getItem('se_theme');
    if(storedTheme) { document.body.setAttribute('data-theme', storedTheme); if(document.getElementById('theme-toggle')) document.getElementById('theme-toggle').checked = (storedTheme === 'dark'); }
    const storedCurr = localStorage.getItem('se_curr');
    if(storedCurr) { App.State.currency = storedCurr; App.Utils.el('curr-btn').innerText = storedCurr; App.Utils.el('setting-curr-display').innerText = storedCurr; }

    App.Router.go('home');
    App.API.init();
    App.Auth.check();
    App.Cart.render();
});
